#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize output
    bins.fill(0);

    #pragma omp parallel
    {
        // Thread-local histogram to avoid races
        std::array<size_t, 10> local{};
        local.fill(0);

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Values are stated to be in [0, 100], inclusive.
            // Map 100 to the last bin (90-100 inclusive for this edge case).
            int b = static_cast<int>(v / 10.0);
            if (b < 0) b = 0;
            if (b > 9) b = 9;

            local[static_cast<std::size_t>(b)] += 1;
        }

        // Combine into global bins safely
        #pragma omp critical
        {
            for (std::size_t k = 0; k < 10; ++k) {
                bins[k] += local[k];
            }
        }
    }
}
